<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Market; use App\Services\MarketService; use Illuminate\Http\Request; use Illuminate\Support\Str;
class MarketController extends Controller {public function index(){return view('admin.markets.index',['markets'=>Market::orderBy('sort_order')->orderBy('name')->get()]);} public function store(Request $r,MarketService $s){$d=$r->validate(['name'=>'required|string|max:120','code'=>'nullable|string|max:32','country_code'=>'required|string|size:2','default_currency_code'=>'required|string|size:3','is_active'=>'boolean','is_default'=>'boolean','sort_order'=>'integer|min:0']);$d['code']=Str::slug($d['code']?:$d['name']);$d['country_code']=strtoupper($d['country_code']);$d['default_currency_code']=strtoupper($d['default_currency_code']);$s->save($d);$s->clear();return back();} public function update(Request $r,Market $market,MarketService $s){$d=$r->validate(['name'=>'required|string|max:120','code'=>'required|string|max:32','country_code'=>'required|string|size:2','default_currency_code'=>'required|string|size:3','is_active'=>'boolean','is_default'=>'boolean','sort_order'=>'integer|min:0']);$d['country_code']=strtoupper($d['country_code']);$d['default_currency_code']=strtoupper($d['default_currency_code']);if(!$d['is_active']&&$market->is_default)abort(422,'Choose another default market first.');$s->save($d,$market);$s->clear();return back();}}
